/// `RouteOut` is the callback type for routing `AdjustedPositionReport` messages.
pub type RouteOut = fn(msg: AdjustedPositionReport, session_id: SessionID) -> Result<(), MessageRejectErrorEnum>;

/// Route type returned by the `route` function.
pub type Route = (&'static str, &'static str, Box<dyn Fn(&Message, SessionID) -> Result<(), MessageRejectErrorEnum> + Send>);

/// Returns the begin string, message type, and route function for `AdjustedPositionReport`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(AdjustedPositionReport::from_message(msg.clone()), session_id)
    };
    ("7", "BL", Box::new(r))
}
